insert into public.programs (slug,title,short,description,age_group,schedule_text,price_text,color,photos,is_active,is_published,sort_order) values (E'mini-sadok',E'Міні-садок',E'Затишна альтернатива великому садочку: маленька група, турбота й розвиток щодня.',E'Міні-садок — це день, наповнений іграми, заняттями, творчістю та відпочинком у невеликій групі. Педагоги допомагають малюкам адаптуватися, вчитися самостійності й дружити.\n\nУмови перебування, вік і вартість уточнюйте за телефоном.',E'',E'',E'',E'red',array[]::text[],true,true,10) on conflict (slug) do nothing;
insert into public.programs (slug,title,short,description,age_group,schedule_text,price_text,color,photos,is_active,is_published,sort_order) values (E'rozvyvaiuchi-zaniattia',E'Розвиваючі заняття',E'Мовлення, логіка, моторика, творчість — заняття, які дитина чекає з нетерпінням.',E'Розвиваючі заняття допомагають дитині гармонійно рости: розвивати мовлення, увагу, пам''ять, дрібну моторику та уяву. Усе — у форматі гри, з урахуванням віку.\n\nГрупи, вік і розклад уточнюйте за телефоном.',E'',E'',E'',E'orange',array[]::text[],true,true,20) on conflict (slug) do nothing;
insert into public.programs (slug,title,short,description,age_group,schedule_text,price_text,color,photos,is_active,is_published,sort_order) values (E'pidhotovka-do-shkoly',E'Підготовка до школи',E'Читання, письмо, математика й логіка — щоб перший клас став радісним стартом.',E'Готуємо дитину до школи комплексно: грамота, читання і письмо, математика та логіка, знайомство з навколишнім світом. А ще — вміння слухати педагога, працювати в групі й не боятися помилок.\n\nФормат, розклад і вартість уточнюйте за телефоном.',E'',E'',E'',E'yellow',array[]::text[],true,true,30) on conflict (slug) do nothing;
insert into public.programs (slug,title,short,description,age_group,schedule_text,price_text,color,photos,is_active,is_published,sort_order) values (E'lohoped',E'Логопед',E'Індивідуальні заняття для чистого, впевненого мовлення.',E'Логопед допомагає дитині правильно вимовляти звуки, збагачувати словник і будувати зв''язне мовлення. Заняття підбираються індивідуально після знайомства з дитиною.\n\nЗапишіться на консультацію — деталі уточнимо телефоном.',E'',E'',E'',E'blue',array[]::text[],true,true,40) on conflict (slug) do nothing;
insert into public.programs (slug,title,short,description,age_group,schedule_text,price_text,color,photos,is_active,is_published,sort_order) values (E'anhliiska-mova',E'Англійська мова',E'Потребує підтвердження центром перед публікацією.',E'Чернетка. Згадується в старих публічних описах центру (2019). Опублікуйте, лише якщо напрям діє зараз.',E'',E'',E'',E'green',array[]::text[],false,false,50) on conflict (slug) do nothing;
