insert into public.posts (slug,kind,title,excerpt,body,event_date,is_published,published_at) values (E'sviato-sviatoho-mykolaia-2026',E'event',E'Свято Святого Миколая',E'Запрошуємо дітей на свято Святого Миколая 4 грудня!',E'Запрошуємо дітей на свято Святого Миколая!\n\nНа малюків чекають:\n• яскраві фотографії з фотозоною;\n• зустріч зі Святим Миколаєм;\n• отримання подарунків;\n• снігова дискотека.\n\nЧас і умови участі уточнюйте за телефоном або в Instagram центру.',E'2026-12-04T12:00:00+02:00',true,E'2026-11-26T12:00:00+02:00') on conflict (slug) do nothing;
